package com.productionhouse.crm.legal.contracts.service;
import com.productionhouse.crm.auth.api.ApiException;import com.productionhouse.crm.legal.contracts.dto.*;import com.productionhouse.crm.legal.contracts.entity.ContractRecord;import com.productionhouse.crm.legal.contracts.repository.ContractRecordRepository;import com.productionhouse.crm.mediahouse.media.entity.MediaAsset;import com.productionhouse.crm.mediahouse.media.repository.MediaAssetRepository;import com.productionhouse.crm.task5.util.Task5Paging;import org.springframework.data.domain.*;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import java.time.LocalDate;import java.util.*;
@Service public class ContractRecordService{
private static final Set<String> STATUSES=Set.of("DRAFT","PENDING","ACTIVE","EXPIRED","TERMINATED");private final ContractRecordRepository repo;private final MediaAssetRepository media;public ContractRecordService(ContractRecordRepository repo,MediaAssetRepository media){this.repo=repo;this.media=media;}
@Transactional(readOnly=true) public Page<ContractResponse> list(String q,String status,String projectRef,String contractType,LocalDate expiresBefore,int page,int size,String sort,String direction){String field=Set.of("name","status","createdAt","updatedAt","endsAt").contains(sort)?sort:"createdAt";Sort order=Sort.by("asc".equalsIgnoreCase(direction)?Sort.Direction.ASC:Sort.Direction.DESC,field);return Task5Paging.page(repo.findAll(order).stream().filter(e->blank(q)||contains(e.getName(),q)||contains(e.getPartyOne(),q)||contains(e.getPartyTwo(),q)).filter(e->blank(status)||status.equalsIgnoreCase(effectiveStatus(e))).filter(e->blank(projectRef)||projectRef.equals(e.getProjectRef())).filter(e->blank(contractType)||contractType.equalsIgnoreCase(e.getContractType())).filter(e->expiresBefore==null||e.getEndsAt()!=null&&!e.getEndsAt().isAfter(expiresBefore)).map(this::response).toList(),page,size);}
@Transactional(readOnly=true) public ContractResponse get(Long id){return response(find(id));}
@Transactional public ContractResponse create(ContractRequest r){return response(save(new ContractRecord(),r));}
@Transactional public ContractResponse update(Long id,ContractRequest r){return response(save(find(id),r));}
@Transactional public void delete(Long id){repo.delete(find(id));}
private ContractRecord find(Long id){return repo.findById(id).orElseThrow(()->ApiException.notFound("Contract not found."));}
private ContractRecord save(ContractRecord e,ContractRequest r){String status=r.status().trim().toUpperCase(Locale.ROOT);if(!STATUSES.contains(status))throw ApiException.badRequest("Unsupported contract status.");if(r.endsAt()!=null&&r.endsAt().isBefore(r.startsAt()))throw ApiException.badRequest("endsAt must be on or after startsAt.");if(r.renewalAt()!=null&&r.renewalAt().isBefore(r.startsAt()))throw ApiException.badRequest("renewalAt must not precede startsAt.");if(e.getId()!=null&&!e.getStatus().equals(status)){boolean allowed=switch(e.getStatus()){case "DRAFT"->Set.of("PENDING","TERMINATED").contains(status);case "PENDING"->Set.of("ACTIVE","TERMINATED").contains(status);case "ACTIVE"->Set.of("EXPIRED","TERMINATED").contains(status);default->false;};if(!allowed)throw ApiException.badRequest("Invalid contract status transition.");}
MediaAsset asset=r.mediaId()==null?null:media.findById(r.mediaId()).orElseThrow(()->ApiException.badRequest("Referenced media asset does not exist."));e.setName(r.name().trim());e.setDescription(clean(r.description()));e.setProjectRef(clean(r.projectRef()));e.setContractType(r.contractType().trim());e.setPartyOne(r.partyOne().trim());e.setPartyTwo(clean(r.partyTwo()));e.setMediaAsset(asset);e.setStatus(status);e.setStartsAt(r.startsAt());e.setEndsAt(r.endsAt());e.setRenewalAt(r.renewalAt());e.setDocumentReference(clean(r.documentReference()));e.setNotes(clean(r.notes()));e.setActive(r.active()==null||r.active());return repo.save(e);}
private String effectiveStatus(ContractRecord e){return "ACTIVE".equals(e.getStatus())&&e.getEndsAt()!=null&&e.getEndsAt().isBefore(LocalDate.now())?"EXPIRED":e.getStatus();}
private ContractResponse response(ContractRecord e){return new ContractResponse(e.getId(),e.getName(),e.getProjectRef(),e.getContractType(),e.getPartyOne(),e.getPartyTwo(),e.getMediaAsset()==null?null:e.getMediaAsset().getId(),effectiveStatus(e),e.getStartsAt(),e.getEndsAt(),e.getRenewalAt(),e.getDocumentReference(),e.isActive(),e.getCreatedAt(),e.getUpdatedAt());}
private boolean blank(String x){return x==null||x.isBlank();}private boolean contains(String x,String q){return x!=null&&x.toLowerCase(Locale.ROOT).contains(q.trim().toLowerCase(Locale.ROOT));}private String clean(String x){return x==null||x.isBlank()?null:x.trim();}}

